(window.ABDI_PAKET = window.ABDI_PAKET || {})["skd.twk.ketatanegaraan.1"] = [{"i":2795,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Menurut UUD NRI 1945, lembaga yang berwenang mengubah dan menetapkan Undang-Undang Dasar adalah …","e":"Pasal 3 ayat (1) UUD NRI 1945 berbunyi: “Majelis Permusyawaratan Rakyat berwenang mengubah dan menetapkan Undang-Undang Dasar.”\nTata cara perubahannya ada di Pasal 37: usul diajukan sekurang-kurangnya 1/3 anggota MPR.\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: UUD adalah hukum tertinggi, jadi yang mengubahnya lembaga yang anggotanya gabungan anggota DPR dan anggota DPD.","o":["Dewan Perwakilan Rakyat","Presiden","Majelis Permusyawaratan Rakyat","Dewan Perwakilan Daerah","Mahkamah Konstitusi"],"s":[0,0,1,0,0],"w":["Menurut Pasal 3 ayat (1) UUD NRI 1945, jawabannya “Majelis Permusyawaratan Rakyat”, bukan “Dewan Perwakilan Rakyat”. DPR memegang kekuasaan membentuk undang-undang (Pasal 20 ayat 1).","Menurut Pasal 3 ayat (1) UUD NRI 1945, jawabannya “Majelis Permusyawaratan Rakyat”, bukan “Presiden”. Presiden memegang kekuasaan pemerintahan (Pasal 4 ayat 1).","Benar. Ini sesuai Pasal 3 ayat (1) UUD NRI 1945.","Menurut Pasal 3 ayat (1) UUD NRI 1945, jawabannya “Majelis Permusyawaratan Rakyat”, bukan “Dewan Perwakilan Daerah”. DPD dapat mengajukan dan ikut membahas RUU tertentu, misalnya yang berkaitan dengan otonomi daerah (Pasal 22D).","Menurut Pasal 3 ayat (1) UUD NRI 1945, jawabannya “Majelis Permusyawaratan Rakyat”, bukan “Mahkamah Konstitusi”. MK menguji undang-undang terhadap UUD, memutus sengketa kewenangan lembaga negara, pembubaran partai politik, dan perselisihan hasil pemilu (Pasal 24C ayat 1)."],"h":"UUD adalah hukum tertinggi, jadi yang mengubahnya lembaga yang anggotanya gabungan anggota DPR dan anggota DPD."},{"i":2796,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Lembaga yang melantik Presiden dan/atau Wakil Presiden adalah …","e":"Pasal 3 ayat (2) UUD NRI 1945 berbunyi: “Majelis Permusyawaratan Rakyat melantik Presiden dan/atau Wakil Presiden.”\nKPU hanya menetapkan hasil pemilu. Bila MPR atau DPR tidak dapat bersidang, sumpah diucapkan di hadapan pimpinan MPR dengan disaksikan pimpinan Mahkamah Agung (Pasal 9 ayat 2).\nCara cepat: Lembaga yang melantik sama dengan lembaga yang berwenang memberhentikan Presiden (Pasal 3 ayat 3).","o":["Mahkamah Agung","Mahkamah Konstitusi","Komisi Pemilihan Umum","Majelis Permusyawaratan Rakyat","Dewan Perwakilan Rakyat"],"s":[0,0,0,1,0],"w":["Menurut Pasal 3 ayat (2) UUD NRI 1945, jawabannya “Majelis Permusyawaratan Rakyat”, bukan “Mahkamah Agung”. MA mengadili pada tingkat kasasi dan menguji peraturan di bawah undang-undang terhadap undang-undang (Pasal 24A ayat 1).","Menurut Pasal 3 ayat (2) UUD NRI 1945, jawabannya “Majelis Permusyawaratan Rakyat”, bukan “Mahkamah Konstitusi”. MK menguji undang-undang terhadap UUD, memutus sengketa kewenangan lembaga negara, pembubaran partai politik, dan perselisihan hasil pemilu (Pasal 24C ayat 1).","Menurut Pasal 3 ayat (2) UUD NRI 1945, jawabannya “Majelis Permusyawaratan Rakyat”, bukan “Komisi Pemilihan Umum”. Komisi pemilihan umum menyelenggarakan pemilu (Pasal 22E ayat 5).","Benar. Ini sesuai Pasal 3 ayat (2) UUD NRI 1945.","Menurut Pasal 3 ayat (2) UUD NRI 1945, jawabannya “Majelis Permusyawaratan Rakyat”, bukan “Dewan Perwakilan Rakyat”. DPR memegang kekuasaan membentuk undang-undang (Pasal 20 ayat 1)."],"h":"Lembaga yang melantik sama dengan lembaga yang berwenang memberhentikan Presiden (Pasal 3 ayat 3)."},{"i":2797,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Menurut UUD NRI 1945, yang memegang kekuasaan pemerintahan adalah …","e":"Pasal 4 ayat (1) UUD NRI 1945 berbunyi: “Presiden Republik Indonesia memegang kekuasaan pemerintahan menurut Undang-Undang Dasar.”\nWakil Presiden membantu Presiden (Pasal 4 ayat 2), begitu pula menteri-menteri negara (Pasal 17 ayat 1).\nBunyi ini sudah ada sejak naskah asli UUD 1945.\nCara cepat: Kekuasaan pemerintahan (eksekutif) dipegang kepala negara sekaligus kepala pemerintahan; para pembantunya tidak memegang kekuasaan itu.","o":["Dewan Perwakilan Rakyat","Wakil Presiden","Presiden","Menteri Dalam Negeri","Majelis Permusyawaratan Rakyat"],"s":[0,0,1,0,0],"w":["Menurut Pasal 4 ayat (1) UUD NRI 1945, jawabannya “Presiden”, bukan “Dewan Perwakilan Rakyat”. DPR memegang kekuasaan membentuk undang-undang (Pasal 20 ayat 1).","Menurut Pasal 4 ayat (1) UUD NRI 1945, jawabannya “Presiden”, bukan “Wakil Presiden”. Wakil Presiden membantu Presiden menjalankan kewajibannya (Pasal 4 ayat 2).","Benar. Ini sesuai Pasal 4 ayat (1) UUD NRI 1945.","Menurut Pasal 4 ayat (1) UUD NRI 1945, jawabannya “Presiden”, bukan “Menteri Dalam Negeri”. “Menteri Dalam Negeri” ada di ketentuan lain, Pasal 8 ayat (3) UUD NRI 1945: “…secara bersamaan, pelaksana tugas kepresidenan adalah Menteri Luar Negeri, Menteri Dalam Negeri, dan Menteri Pertahanan secara bersamasama. Selambat-lambatnya tiga puluh…”","Menurut Pasal 4 ayat (1) UUD NRI 1945, jawabannya “Presiden”, bukan “Majelis Permusyawaratan Rakyat”. MPR berwenang mengubah dan menetapkan UUD (Pasal 3 ayat 1)."],"h":"Kekuasaan pemerintahan (eksekutif) dipegang kepala negara sekaligus kepala pemerintahan; para pembantunya tidak memegang kekuasaan itu."},{"i":2798,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Peraturan pemerintah untuk menjalankan undang-undang ditetapkan oleh …","e":"Pasal 5 ayat (2) UUD NRI 1945 berbunyi: “Presiden menetapkan peraturan pemerintah untuk menjalankan undang-undang sebagaimana mestinya.”\nBedakan dengan undang-undang, yang dibahas DPR dan Presiden untuk mendapat persetujuan bersama (Pasal 20 ayat 2).\nBunyi ini sudah ada sejak naskah asli UUD 1945.\nCara cepat: Undang-undang dibuat bersama DPR, tetapi aturan pelaksananya cukup ditetapkan pemegang kekuasaan pemerintahan.","o":["Menteri terkait","Mahkamah Agung","Dewan Perwakilan Rakyat","Presiden","Majelis Permusyawaratan Rakyat"],"s":[0,0,0,1,0],"w":["Menurut Pasal 5 ayat (2) UUD NRI 1945, jawabannya “Presiden”, bukan “Menteri terkait”.","Menurut Pasal 5 ayat (2) UUD NRI 1945, jawabannya “Presiden”, bukan “Mahkamah Agung”. MA mengadili pada tingkat kasasi dan menguji peraturan di bawah undang-undang terhadap undang-undang (Pasal 24A ayat 1).","Menurut Pasal 5 ayat (2) UUD NRI 1945, jawabannya “Presiden”, bukan “Dewan Perwakilan Rakyat”. DPR memegang kekuasaan membentuk undang-undang (Pasal 20 ayat 1).","Benar. Ini sesuai Pasal 5 ayat (2) UUD NRI 1945.","Menurut Pasal 5 ayat (2) UUD NRI 1945, jawabannya “Presiden”, bukan “Majelis Permusyawaratan Rakyat”. MPR berwenang mengubah dan menetapkan UUD (Pasal 3 ayat 1)."],"h":"Undang-undang dibuat bersama DPR, tetapi aturan pelaksananya cukup ditetapkan pemegang kekuasaan pemerintahan."},{"i":2799,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Kekuasaan yang tertinggi atas Angkatan Darat, Angkatan Laut, dan Angkatan Udara dipegang oleh …","e":"Pasal 10 UUD NRI 1945 berbunyi: “Presiden memegang kekuasaan yang tertinggi atas Angkatan Darat, Angkatan Laut, dan Angkatan Udara.”\nPanglima TNI memimpin TNI, tetapi kekuasaan tertinggi atas ketiga angkatan ada pada Presiden.\nBunyi ini sudah ada sejak naskah asli UUD 1945.\nCara cepat: Kata kuncinya 'tertinggi': di atas panglima dan menteri masih ada kepala negara.","o":["Menteri Pertahanan","Majelis Permusyawaratan Rakyat","Presiden","Dewan Perwakilan Rakyat","Panglima TNI"],"s":[0,0,1,0,0],"w":["Menurut Pasal 10 UUD NRI 1945, jawabannya “Presiden”, bukan “Menteri Pertahanan”. “Menteri Pertahanan” ada di ketentuan lain, Pasal 8 ayat (3) UUD NRI 1945: “…tugas kepresidenan adalah Menteri Luar Negeri, Menteri Dalam Negeri, dan Menteri Pertahanan secara bersamasama. Selambat-lambatnya tiga puluh hari setelah itu, Majelis…”","Menurut Pasal 10 UUD NRI 1945, jawabannya “Presiden”, bukan “Majelis Permusyawaratan Rakyat”. MPR berwenang mengubah dan menetapkan UUD (Pasal 3 ayat 1).","Benar. Ini sesuai Pasal 10 UUD NRI 1945.","Menurut Pasal 10 UUD NRI 1945, jawabannya “Presiden”, bukan “Dewan Perwakilan Rakyat”. DPR memegang kekuasaan membentuk undang-undang (Pasal 20 ayat 1).","Menurut Pasal 10 UUD NRI 1945, jawabannya “Presiden”, bukan “Panglima TNI”."],"h":"Kata kuncinya 'tertinggi': di atas panglima dan menteri masih ada kepala negara."},{"i":2800,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Presiden menyatakan perang, membuat perdamaian, dan perjanjian dengan negara lain dengan persetujuan …","e":"Pasal 11 ayat (1) UUD NRI 1945 berbunyi: “Presiden dengan persetujuan Dewan Perwakilan Rakyat menyatakan perang, membuat perdamaian dan perjanjian dengan negara lain.”\nPerjanjian internasional lain yang berdampak luas bagi rakyat juga harus dengan persetujuan DPR (Pasal 11 ayat 2).\nCara cepat: Keputusan besar Presiden yang menyangkut seluruh rakyat butuh persetujuan lembaga pembentuk undang-undang.","o":["Menteri Luar Negeri","Dewan Perwakilan Daerah","Majelis Permusyawaratan Rakyat","Mahkamah Konstitusi","Dewan Perwakilan Rakyat"],"s":[0,0,0,0,1],"w":["Menurut Pasal 11 ayat (1) UUD NRI 1945, jawabannya “Dewan Perwakilan Rakyat”, bukan “Menteri Luar Negeri”. “Menteri Luar Negeri” ada di ketentuan lain, Pasal 8 ayat (3) UUD NRI 1945: “…masa jabatannya secara bersamaan, pelaksana tugas kepresidenan adalah Menteri Luar Negeri, Menteri Dalam Negeri, dan Menteri Pertahanan secara bersamasama. Selambat-lambatnya…”","Menurut Pasal 11 ayat (1) UUD NRI 1945, jawabannya “Dewan Perwakilan Rakyat”, bukan “Dewan Perwakilan Daerah”. DPD dapat mengajukan dan ikut membahas RUU tertentu, misalnya yang berkaitan dengan otonomi daerah (Pasal 22D).","Menurut Pasal 11 ayat (1) UUD NRI 1945, jawabannya “Dewan Perwakilan Rakyat”, bukan “Majelis Permusyawaratan Rakyat”. MPR berwenang mengubah dan menetapkan UUD (Pasal 3 ayat 1).","Menurut Pasal 11 ayat (1) UUD NRI 1945, jawabannya “Dewan Perwakilan Rakyat”, bukan “Mahkamah Konstitusi”. MK menguji undang-undang terhadap UUD, memutus sengketa kewenangan lembaga negara, pembubaran partai politik, dan perselisihan hasil pemilu (Pasal 24C ayat 1).","Benar. Ini sesuai Pasal 11 ayat (1) UUD NRI 1945."],"h":"Keputusan besar Presiden yang menyangkut seluruh rakyat butuh persetujuan lembaga pembentuk undang-undang."},{"i":2801,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Dalam hal mengangkat duta, Presiden memperhatikan pertimbangan …","e":"Pasal 13 ayat (2) UUD NRI 1945 berbunyi: “Dalam hal mengangkat duta, Presiden memperhatikan pertimbangan Dewan Perwakilan Rakyat.”\nBegitu pula saat Presiden menerima penempatan duta negara lain (Pasal 13 ayat 3).\nAyat ini dirumuskan dalam Perubahan Pertama (1999).\nCara cepat: Pengangkatan dan penerimaan duta memperhatikan pertimbangan lembaga perwakilan rakyat, bukan lembaga perwakilan daerah.","o":["Mahkamah Agung","Dewan Perwakilan Daerah","Majelis Permusyawaratan Rakyat","Dewan Perwakilan Rakyat","Menteri Luar Negeri"],"s":[0,0,0,1,0],"w":["Menurut Pasal 13 ayat (2) UUD NRI 1945, jawabannya “Dewan Perwakilan Rakyat”, bukan “Mahkamah Agung”. MA mengadili pada tingkat kasasi dan menguji peraturan di bawah undang-undang terhadap undang-undang (Pasal 24A ayat 1).","Menurut Pasal 13 ayat (2) UUD NRI 1945, jawabannya “Dewan Perwakilan Rakyat”, bukan “Dewan Perwakilan Daerah”. DPD dapat mengajukan dan ikut membahas RUU tertentu, misalnya yang berkaitan dengan otonomi daerah (Pasal 22D).","Menurut Pasal 13 ayat (2) UUD NRI 1945, jawabannya “Dewan Perwakilan Rakyat”, bukan “Majelis Permusyawaratan Rakyat”. MPR berwenang mengubah dan menetapkan UUD (Pasal 3 ayat 1).","Benar. Ini sesuai Pasal 13 ayat (2) UUD NRI 1945.","Menurut Pasal 13 ayat (2) UUD NRI 1945, jawabannya “Dewan Perwakilan Rakyat”, bukan “Menteri Luar Negeri”. “Menteri Luar Negeri” ada di ketentuan lain, Pasal 8 ayat (3) UUD NRI 1945: “…masa jabatannya secara bersamaan, pelaksana tugas kepresidenan adalah Menteri Luar Negeri, Menteri Dalam Negeri, dan Menteri Pertahanan secara bersamasama. Selambat-lambatnya…”"],"h":"Pengangkatan dan penerimaan duta memperhatikan pertimbangan lembaga perwakilan rakyat, bukan lembaga perwakilan daerah."},{"i":2802,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Presiden memberi grasi dan rehabilitasi dengan memperhatikan pertimbangan …","e":"Pasal 14 ayat (1) UUD NRI 1945 berbunyi: “Presiden memberi grasi dan rehabilitasi dengan memperhatikan pertimbangan Mahkamah Agung.”\nPasangannya: amnesti dan abolisi dengan memperhatikan pertimbangan DPR (Pasal 14 ayat 2).\nAyat ini dirumuskan dalam Perubahan Pertama (1999).\nCara cepat: Grasi dan rehabilitasi menyangkut putusan pengadilan atas orang per orang, jadi pertimbangannya dari puncak peradilan. Amnesti dan abolisi bersifat politis, pertimbangannya dari lembaga perwakilan rakyat.","o":["Jaksa Agung","Komisi Yudisial","Mahkamah Konstitusi","Dewan Perwakilan Rakyat","Mahkamah Agung"],"s":[0,0,0,0,1],"w":["Menurut Pasal 14 ayat (1) UUD NRI 1945, jawabannya “Mahkamah Agung”, bukan “Jaksa Agung”.","Menurut Pasal 14 ayat (1) UUD NRI 1945, jawabannya “Mahkamah Agung”, bukan “Komisi Yudisial”. KY mengusulkan pengangkatan hakim agung dan menjaga kehormatan serta perilaku hakim (Pasal 24B ayat 1).","Menurut Pasal 14 ayat (1) UUD NRI 1945, jawabannya “Mahkamah Agung”, bukan “Mahkamah Konstitusi”. MK menguji undang-undang terhadap UUD, memutus sengketa kewenangan lembaga negara, pembubaran partai politik, dan perselisihan hasil pemilu (Pasal 24C ayat 1).","Pertimbangan DPR dipakai untuk amnesti dan abolisi (Pasal 14 ayat 2), bukan grasi dan rehabilitasi.","Benar. Ini sesuai Pasal 14 ayat (1) UUD NRI 1945."],"h":"Grasi dan rehabilitasi menyangkut putusan pengadilan atas orang per orang, jadi pertimbangannya dari puncak peradilan. Amnesti dan abolisi bersifat politis, pertimbangannya dari lembaga perwakilan rakyat."},{"i":2803,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Presiden memberi amnesti dan abolisi dengan memperhatikan pertimbangan …","e":"Pasal 14 ayat (2) UUD NRI 1945 berbunyi: “Presiden memberi amnesti dan abolisi dengan memperhatikan pertimbangan Dewan Perwakilan Rakyat.”\nPasangannya: grasi dan rehabilitasi dengan memperhatikan pertimbangan Mahkamah Agung (Pasal 14 ayat 1).\nAyat ini dirumuskan dalam Perubahan Pertama (1999).\nCara cepat: Grasi dan rehabilitasi (putusan pengadilan perorangan) → puncak peradilan. Amnesti dan abolisi (kebijakan politis, sering untuk banyak orang) → lembaga perwakilan rakyat.","o":["Mahkamah Konstitusi","Majelis Permusyawaratan Rakyat","Dewan Perwakilan Rakyat","Mahkamah Agung","Komisi Yudisial"],"s":[0,0,1,0,0],"w":["Menurut Pasal 14 ayat (2) UUD NRI 1945, jawabannya “Dewan Perwakilan Rakyat”, bukan “Mahkamah Konstitusi”. MK menguji undang-undang terhadap UUD, memutus sengketa kewenangan lembaga negara, pembubaran partai politik, dan perselisihan hasil pemilu (Pasal 24C ayat 1).","Menurut Pasal 14 ayat (2) UUD NRI 1945, jawabannya “Dewan Perwakilan Rakyat”, bukan “Majelis Permusyawaratan Rakyat”. MPR berwenang mengubah dan menetapkan UUD (Pasal 3 ayat 1).","Benar. Ini sesuai Pasal 14 ayat (2) UUD NRI 1945.","Pertimbangan MA dipakai untuk grasi dan rehabilitasi (Pasal 14 ayat 1), bukan amnesti dan abolisi.","Menurut Pasal 14 ayat (2) UUD NRI 1945, jawabannya “Dewan Perwakilan Rakyat”, bukan “Komisi Yudisial”. KY mengusulkan pengangkatan hakim agung dan menjaga kehormatan serta perilaku hakim (Pasal 24B ayat 1)."],"h":"Grasi dan rehabilitasi (putusan pengadilan perorangan) → puncak peradilan. Amnesti dan abolisi (kebijakan politis, sering untuk banyak orang) → lembaga perwakilan rakyat."},{"i":2804,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Dewan yang bertugas memberikan nasihat dan pertimbangan kepada Presiden dibentuk oleh …","e":"Pasal 16 UUD NRI 1945 berbunyi: “Presiden membentuk suatu dewan pertimbangan yang bertugas memberikan nasihat dan pertimbangan kepada Presiden, yang selanjutnya diatur dalam undang-undang.”\nDulu ada Dewan Pertimbangan Agung di Bab IV. Perubahan Keempat menghapus bab itu; kini dewan pertimbangan dibentuk Presiden dan diatur undang-undang.\nAyat ini dirumuskan dalam Perubahan Keempat (2002).\nCara cepat: Dewan ini menasihati kepala negara, jadi yang membentuknya pihak yang dinasihati.","o":["Presiden","Dewan Perwakilan Daerah","Dewan Perwakilan Rakyat","Majelis Permusyawaratan Rakyat","Mahkamah Agung"],"s":[1,0,0,0,0],"w":["Benar. Ini sesuai Pasal 16 UUD NRI 1945.","Menurut Pasal 16 UUD NRI 1945, jawabannya “Presiden”, bukan “Dewan Perwakilan Daerah”. DPD dapat mengajukan dan ikut membahas RUU tertentu, misalnya yang berkaitan dengan otonomi daerah (Pasal 22D).","Menurut Pasal 16 UUD NRI 1945, jawabannya “Presiden”, bukan “Dewan Perwakilan Rakyat”. DPR memegang kekuasaan membentuk undang-undang (Pasal 20 ayat 1).","Menurut Pasal 16 UUD NRI 1945, jawabannya “Presiden”, bukan “Majelis Permusyawaratan Rakyat”. MPR berwenang mengubah dan menetapkan UUD (Pasal 3 ayat 1).","Menurut Pasal 16 UUD NRI 1945, jawabannya “Presiden”, bukan “Mahkamah Agung”. MA mengadili pada tingkat kasasi dan menguji peraturan di bawah undang-undang terhadap undang-undang (Pasal 24A ayat 1)."],"h":"Dewan ini menasihati kepala negara, jadi yang membentuknya pihak yang dinasihati."},{"i":2805,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Menteri-menteri negara diangkat dan diberhentikan oleh …","e":"Pasal 17 ayat (2) UUD NRI 1945 berbunyi: “Menteri-menteri itu diangkat dan diberhentikan oleh Presiden.”\nIni ciri sistem presidensial: menteri bertanggung jawab kepada Presiden, bukan kepada DPR.\nAyat ini dirumuskan dalam Perubahan Pertama (1999).\nCara cepat: Menteri adalah pembantu kepala pemerintahan (Pasal 17 ayat 1). Pembantu dipilih dan diganti oleh yang dibantu, tanpa persetujuan lembaga lain.","o":["Dewan Perwakilan Rakyat","Presiden dengan persetujuan DPR","Wakil Presiden","Presiden","Majelis Permusyawaratan Rakyat"],"s":[0,0,0,1,0],"w":["Menurut Pasal 17 ayat (2) UUD NRI 1945, jawabannya “Presiden”, bukan “Dewan Perwakilan Rakyat”. DPR memegang kekuasaan membentuk undang-undang (Pasal 20 ayat 1).","Menurut Pasal 17 ayat (2) UUD NRI 1945, jawabannya “Presiden”, bukan “Presiden dengan persetujuan DPR”.","Menurut Pasal 17 ayat (2) UUD NRI 1945, jawabannya “Presiden”, bukan “Wakil Presiden”. Wakil Presiden membantu Presiden menjalankan kewajibannya (Pasal 4 ayat 2).","Benar. Ini sesuai Pasal 17 ayat (2) UUD NRI 1945.","Menurut Pasal 17 ayat (2) UUD NRI 1945, jawabannya “Presiden”, bukan “Majelis Permusyawaratan Rakyat”. MPR berwenang mengubah dan menetapkan UUD (Pasal 3 ayat 1)."],"h":"Menteri adalah pembantu kepala pemerintahan (Pasal 17 ayat 1). Pembantu dipilih dan diganti oleh yang dibantu, tanpa persetujuan lembaga lain."},{"i":2806,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Menurut UUD NRI 1945 setelah perubahan, kekuasaan membentuk undang-undang dipegang oleh …","e":"Pasal 20 ayat (1) UUD NRI 1945 berbunyi: “Dewan Perwakilan Rakyat memegang kekuasaan membentuk undang-undang.”\nSebelum Perubahan Pertama (1999), Pasal 5 ayat (1) berbunyi: Presiden memegang kekuasaan membentuk undang-undang dengan persetujuan DPR. Sekarang tiap RUU tetap dibahas bersama DPR dan Presiden (Pasal 20 ayat 2).\nAyat ini dirumuskan dalam Perubahan Pertama (1999).\nCara cepat: Perubahan Pertama memindahkan kekuasaan membentuk UU dari kepala pemerintahan ke lembaga legislatif; Presiden tinggal berhak mengajukan RUU.","o":["Dewan Perwakilan Rakyat","Dewan Perwakilan Daerah","Majelis Permusyawaratan Rakyat","Mahkamah Konstitusi","Presiden"],"s":[1,0,0,0,0],"w":["Benar. Ini sesuai Pasal 20 ayat (1) UUD NRI 1945.","Menurut Pasal 20 ayat (1) UUD NRI 1945, jawabannya “Dewan Perwakilan Rakyat”, bukan “Dewan Perwakilan Daerah”. DPD dapat mengajukan dan ikut membahas RUU tertentu, misalnya yang berkaitan dengan otonomi daerah (Pasal 22D).","Menurut Pasal 20 ayat (1) UUD NRI 1945, jawabannya “Dewan Perwakilan Rakyat”, bukan “Majelis Permusyawaratan Rakyat”. MPR berwenang mengubah dan menetapkan UUD (Pasal 3 ayat 1).","Menurut Pasal 20 ayat (1) UUD NRI 1945, jawabannya “Dewan Perwakilan Rakyat”, bukan “Mahkamah Konstitusi”. MK menguji undang-undang terhadap UUD, memutus sengketa kewenangan lembaga negara, pembubaran partai politik, dan perselisihan hasil pemilu (Pasal 24C ayat 1).","Sebelum Perubahan Pertama (1999), kekuasaan itu dipegang Presiden. Sekarang Presiden berhak mengajukan RUU (Pasal 5 ayat 1) dan membahasnya bersama DPR (Pasal 20 ayat 2)."],"h":"Perubahan Pertama memindahkan kekuasaan membentuk UU dari kepala pemerintahan ke lembaga legislatif; Presiden tinggal berhak mengajukan RUU."},{"i":2807,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Lembaga yang dapat mengajukan kepada DPR rancangan undang-undang yang berkaitan dengan otonomi daerah serta hubungan pusat dan daerah adalah …","e":"Pasal 22D ayat (1) UUD NRI 1945 berbunyi: “Dewan Perwakilan Daerah dapat mengajukan kepada Dewan Perwakilan Rakyat rancangan undang-undang yang berkaitan dengan otonomi daerah, hubungan pusat dan daerah, pembentukan dan pemekaran serta penggabungan daerah, pengelolaan sumber daya alam dan sumber daya ekonomi lainnya, serta yang berkaitan dengan perimbangan keuangan pusat dan daerah.”\nDPD juga ikut membahas RUU tersebut dan mengawasi pelaksanaannya (Pasal 22D ayat 2 dan 3).\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Topiknya serba daerah (otonomi, pemekaran, sumber daya daerah), jadi pengusulnya lembaga yang mewakili daerah.","o":["Dewan Perwakilan Daerah","Majelis Permusyawaratan Rakyat","Komisi Yudisial","Mahkamah Agung","Badan Pemeriksa Keuangan"],"s":[1,0,0,0,0],"w":["Benar. Ini sesuai Pasal 22D ayat (1) UUD NRI 1945.","Menurut Pasal 22D ayat (1) UUD NRI 1945, jawabannya “Dewan Perwakilan Daerah”, bukan “Majelis Permusyawaratan Rakyat”. MPR berwenang mengubah dan menetapkan UUD (Pasal 3 ayat 1).","Menurut Pasal 22D ayat (1) UUD NRI 1945, jawabannya “Dewan Perwakilan Daerah”, bukan “Komisi Yudisial”. KY mengusulkan pengangkatan hakim agung dan menjaga kehormatan serta perilaku hakim (Pasal 24B ayat 1).","Menurut Pasal 22D ayat (1) UUD NRI 1945, jawabannya “Dewan Perwakilan Daerah”, bukan “Mahkamah Agung”. MA mengadili pada tingkat kasasi dan menguji peraturan di bawah undang-undang terhadap undang-undang (Pasal 24A ayat 1).","Menurut Pasal 22D ayat (1) UUD NRI 1945, jawabannya “Dewan Perwakilan Daerah”, bukan “Badan Pemeriksa Keuangan”. BPK memeriksa pengelolaan dan tanggung jawab keuangan negara (Pasal 23E ayat 1)."],"h":"Topiknya serba daerah (otonomi, pemekaran, sumber daya daerah), jadi pengusulnya lembaga yang mewakili daerah."},{"i":2808,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Menurut UUD NRI 1945, pemilihan umum diselenggarakan oleh …","e":"Pasal 22E ayat (5) UUD NRI 1945 berbunyi: “Pemilihan umum diselenggarakan oleh suatu komisi pemilihan umum yang bersifat nasional, tetap, dan mandiri.”\nUUD menulis 'komisi pemilihan umum' dengan huruf kecil; nama lembaganya diatur dalam undang-undang pemilu.\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Supaya netral, penyelenggara pemilu tidak boleh berada di bawah pemerintah atau peserta pemilu.","o":["Kementerian Dalam Negeri","Mahkamah Konstitusi","pemerintah daerah di setiap provinsi","suatu komisi pemilihan umum yang bersifat nasional, tetap, dan mandiri","Dewan Perwakilan Rakyat bersama Presiden"],"s":[0,0,0,1,0],"w":["Menurut Pasal 22E ayat (5) UUD NRI 1945, jawabannya “suatu komisi pemilihan umum yang bersifat nasional, tetap, dan mandiri”, bukan “Kementerian Dalam Negeri”.","Menurut Pasal 22E ayat (5) UUD NRI 1945, jawabannya “suatu komisi pemilihan umum yang bersifat nasional, tetap, dan mandiri”, bukan “Mahkamah Konstitusi”. MK menguji undang-undang terhadap UUD, memutus sengketa kewenangan lembaga negara, pembubaran partai politik, dan perselisihan hasil pemilu (Pasal 24C ayat 1).","Menurut Pasal 22E ayat (5) UUD NRI 1945, jawabannya “suatu komisi pemilihan umum yang bersifat nasional, tetap, dan mandiri”, bukan “pemerintah daerah di setiap provinsi”.","Benar. Ini sesuai Pasal 22E ayat (5) UUD NRI 1945.","Menurut Pasal 22E ayat (5) UUD NRI 1945, jawabannya “suatu komisi pemilihan umum yang bersifat nasional, tetap, dan mandiri”, bukan “Dewan Perwakilan Rakyat bersama Presiden”."],"h":"Supaya netral, penyelenggara pemilu tidak boleh berada di bawah pemerintah atau peserta pemilu."},{"i":2809,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Lembaga yang dibentuk untuk memeriksa pengelolaan dan tanggung jawab tentang keuangan negara adalah …","e":"Pasal 23E ayat (1) UUD NRI 1945 berbunyi: “Untuk memeriksa pengelolaan dan tanggung jawab tentang keuangan negara diadakan satu Badan Pemeriksa Keuangan yang bebas dan mandiri.”\nBPK bersifat bebas dan mandiri. Hasil pemeriksaannya diserahkan kepada DPR, DPD, dan DPRD sesuai kewenangannya (Pasal 23E ayat 2).\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Lihat kata kerjanya: 'memeriksa' keuangan negara. Cari lembaga yang namanya memuat kata itu.","o":["Kementerian Keuangan","Bank sentral","Mahkamah Agung","Badan Pemeriksa Keuangan","Dewan Perwakilan Rakyat"],"s":[0,0,0,1,0],"w":["Menurut Pasal 23E ayat (1) UUD NRI 1945, jawabannya “Badan Pemeriksa Keuangan”, bukan “Kementerian Keuangan”.","Menurut Pasal 23E ayat (1) UUD NRI 1945, jawabannya “Badan Pemeriksa Keuangan”, bukan “Bank sentral”. “Bank sentral” ada di ketentuan lain, Pasal 23D UUD NRI 1945: “Negara memiliki suatu bank sentral yang susunan, kedudukan, kewenangan, tanggung jawab, dan independensinya diatur dengan undang-undang.”","Menurut Pasal 23E ayat (1) UUD NRI 1945, jawabannya “Badan Pemeriksa Keuangan”, bukan “Mahkamah Agung”. MA mengadili pada tingkat kasasi dan menguji peraturan di bawah undang-undang terhadap undang-undang (Pasal 24A ayat 1).","Benar. Ini sesuai Pasal 23E ayat (1) UUD NRI 1945.","Menurut Pasal 23E ayat (1) UUD NRI 1945, jawabannya “Badan Pemeriksa Keuangan”, bukan “Dewan Perwakilan Rakyat”. DPR memegang kekuasaan membentuk undang-undang (Pasal 20 ayat 1)."],"h":"Lihat kata kerjanya: 'memeriksa' keuangan negara. Cari lembaga yang namanya memuat kata itu."},{"i":2810,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Anggota Badan Pemeriksa Keuangan dipilih oleh …","e":"Pasal 23F ayat (1) UUD NRI 1945 berbunyi: “Anggota Badan Pemeriksa Keuangan dipilih oleh Dewan Perwakilan Rakyat dengan memperhatikan pertimbangan Dewan Perwakilan Daerah dan diresmikan oleh Presiden.”\nLengkapnya: dipilih DPR dengan memperhatikan pertimbangan DPD, lalu diresmikan Presiden. Pimpinan BPK dipilih dari dan oleh anggota (Pasal 23F ayat 2).\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Pasal 23F memberi tiga lembaga peran berbeda: satu memilih, satu memberi pertimbangan, satu meresmikan. Yang memilih adalah lembaga yang memegang fungsi anggaran.","o":["Presiden","Mahkamah Agung","Dewan Perwakilan Daerah","Majelis Permusyawaratan Rakyat","Dewan Perwakilan Rakyat"],"s":[0,0,0,0,1],"w":["Presiden meresmikan anggota BPK yang sudah dipilih DPR (Pasal 23F ayat 1).","Menurut Pasal 23F ayat (1) UUD NRI 1945, jawabannya “Dewan Perwakilan Rakyat”, bukan “Mahkamah Agung”. MA mengadili pada tingkat kasasi dan menguji peraturan di bawah undang-undang terhadap undang-undang (Pasal 24A ayat 1).","DPD memberi pertimbangan, tetapi yang memilih anggota BPK adalah DPR (Pasal 23F ayat 1).","Menurut Pasal 23F ayat (1) UUD NRI 1945, jawabannya “Dewan Perwakilan Rakyat”, bukan “Majelis Permusyawaratan Rakyat”. MPR berwenang mengubah dan menetapkan UUD (Pasal 3 ayat 1).","Benar. Ini sesuai Pasal 23F ayat (1) UUD NRI 1945."],"h":"Pasal 23F memberi tiga lembaga peran berbeda: satu memilih, satu memberi pertimbangan, satu meresmikan. Yang memilih adalah lembaga yang memegang fungsi anggaran."},{"i":2811,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Dalam memilih anggota Badan Pemeriksa Keuangan, DPR memperhatikan pertimbangan …","e":"Pasal 23F ayat (1) UUD NRI 1945 berbunyi: “Anggota Badan Pemeriksa Keuangan dipilih oleh Dewan Perwakilan Rakyat dengan memperhatikan pertimbangan Dewan Perwakilan Daerah dan diresmikan oleh Presiden.”\nSetelah dipilih, anggota BPK diresmikan oleh Presiden.\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Keuangan negara juga menyangkut daerah, jadi lembaga yang mewakili daerah ikut memberi pertimbangan.","o":["Mahkamah Agung","Dewan Perwakilan Daerah","Majelis Permusyawaratan Rakyat","Komisi Yudisial","Presiden"],"s":[0,1,0,0,0],"w":["Menurut Pasal 23F ayat (1) UUD NRI 1945, jawabannya “Dewan Perwakilan Daerah”, bukan “Mahkamah Agung”. MA mengadili pada tingkat kasasi dan menguji peraturan di bawah undang-undang terhadap undang-undang (Pasal 24A ayat 1).","Benar. Ini sesuai Pasal 23F ayat (1) UUD NRI 1945.","Menurut Pasal 23F ayat (1) UUD NRI 1945, jawabannya “Dewan Perwakilan Daerah”, bukan “Majelis Permusyawaratan Rakyat”. MPR berwenang mengubah dan menetapkan UUD (Pasal 3 ayat 1).","Menurut Pasal 23F ayat (1) UUD NRI 1945, jawabannya “Dewan Perwakilan Daerah”, bukan “Komisi Yudisial”. KY mengusulkan pengangkatan hakim agung dan menjaga kehormatan serta perilaku hakim (Pasal 24B ayat 1).","Presiden meresmikan anggota BPK setelah dipilih DPR (Pasal 23F ayat 1), bukan memberi pertimbangan."],"h":"Keuangan negara juga menyangkut daerah, jadi lembaga yang mewakili daerah ikut memberi pertimbangan."},{"i":2812,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Lembaga yang berwenang mengadili pada tingkat kasasi adalah …","e":"Pasal 24A ayat (1) UUD NRI 1945 berbunyi: “Mahkamah Agung berwenang mengadili pada tingkat kasasi, menguji peraturan perundang-undangan di bawah undang-undang terhadap undang-undang, dan mempunyai wewenang lainnya yang diberikan oleh undang-undang.”\nMahkamah Konstitusi tidak memeriksa kasasi; ia mengadili pada tingkat pertama dan terakhir untuk perkara konstitusi (Pasal 24C ayat 1).\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Kasasi adalah upaya hukum tingkat terakhir di peradilan umum, agama, militer, dan tata usaha negara; puncaknya lembaga yang membawahi keempat lingkungan peradilan itu (Pasal 24 ayat 2).","o":["Kejaksaan Agung","Mahkamah Agung","Pengadilan Tinggi","Mahkamah Konstitusi","Komisi Yudisial"],"s":[0,1,0,0,0],"w":["Menurut Pasal 24A ayat (1) UUD NRI 1945, jawabannya “Mahkamah Agung”, bukan “Kejaksaan Agung”.","Benar. Ini sesuai Pasal 24A ayat (1) UUD NRI 1945.","Menurut Pasal 24A ayat (1) UUD NRI 1945, jawabannya “Mahkamah Agung”, bukan “Pengadilan Tinggi”.","Menurut Pasal 24A ayat (1) UUD NRI 1945, jawabannya “Mahkamah Agung”, bukan “Mahkamah Konstitusi”. MK menguji undang-undang terhadap UUD, memutus sengketa kewenangan lembaga negara, pembubaran partai politik, dan perselisihan hasil pemilu (Pasal 24C ayat 1).","Menurut Pasal 24A ayat (1) UUD NRI 1945, jawabannya “Mahkamah Agung”, bukan “Komisi Yudisial”. KY mengusulkan pengangkatan hakim agung dan menjaga kehormatan serta perilaku hakim (Pasal 24B ayat 1)."],"h":"Kasasi adalah upaya hukum tingkat terakhir di peradilan umum, agama, militer, dan tata usaha negara; puncaknya lembaga yang membawahi keempat lingkungan peradilan itu (Pasal 24 ayat 2)."},{"i":2813,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Menguji peraturan perundang-undangan di bawah undang-undang terhadap undang-undang adalah wewenang …","e":"Pasal 24A ayat (1) UUD NRI 1945 berbunyi: “Mahkamah Agung berwenang mengadili pada tingkat kasasi, menguji peraturan perundang-undangan di bawah undang-undang terhadap undang-undang, dan mempunyai wewenang lainnya yang diberikan oleh undang-undang.”\nContohnya peraturan pemerintah atau peraturan daerah yang dianggap bertentangan dengan undang-undang.\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Lihat batu ujinya. Kalau batu ujinya UUD, pengujinya peradilan konstitusi; kalau batu ujinya undang-undang, pengujinya puncak peradilan yang juga mengadili kasasi.","o":["Presiden","Mahkamah Konstitusi","Komisi Yudisial","Mahkamah Agung","Dewan Perwakilan Rakyat"],"s":[0,0,0,1,0],"w":["Menurut Pasal 24A ayat (1) UUD NRI 1945, jawabannya “Mahkamah Agung”, bukan “Presiden”. Presiden memegang kekuasaan pemerintahan (Pasal 4 ayat 1).","Menurut Pasal 24A ayat (1) UUD NRI 1945, jawabannya “Mahkamah Agung”, bukan “Mahkamah Konstitusi”. MK menguji undang-undang terhadap UUD, memutus sengketa kewenangan lembaga negara, pembubaran partai politik, dan perselisihan hasil pemilu (Pasal 24C ayat 1).","Menurut Pasal 24A ayat (1) UUD NRI 1945, jawabannya “Mahkamah Agung”, bukan “Komisi Yudisial”. KY mengusulkan pengangkatan hakim agung dan menjaga kehormatan serta perilaku hakim (Pasal 24B ayat 1).","Benar. Ini sesuai Pasal 24A ayat (1) UUD NRI 1945.","Menurut Pasal 24A ayat (1) UUD NRI 1945, jawabannya “Mahkamah Agung”, bukan “Dewan Perwakilan Rakyat”. DPR memegang kekuasaan membentuk undang-undang (Pasal 20 ayat 1)."],"h":"Lihat batu ujinya. Kalau batu ujinya UUD, pengujinya peradilan konstitusi; kalau batu ujinya undang-undang, pengujinya puncak peradilan yang juga mengadili kasasi."},{"i":2814,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Calon hakim agung diusulkan oleh …","e":"Pasal 24A ayat (3) UUD NRI 1945 berbunyi: “Calon hakim agung diusulkan Komisi Yudisial kepada Dewan Perwakilan Rakyat untuk mendapatkan persetujuan dan selanjutnya ditetapkan sebagai hakim agung oleh Presiden.”\nLengkapnya: diusulkan Komisi Yudisial kepada DPR untuk mendapat persetujuan, lalu ditetapkan sebagai hakim agung oleh Presiden.\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Urutannya: diusulkan, disetujui, lalu ditetapkan. Yang mengusulkan adalah lembaga yang dibentuk khusus untuk urusan pengangkatan dan perilaku hakim.","o":["Presiden","Mahkamah Agung","Dewan Perwakilan Rakyat","Mahkamah Konstitusi","Komisi Yudisial"],"s":[0,0,0,0,1],"w":["Presiden menetapkan hakim agung setelah calonnya disetujui DPR (Pasal 24A ayat 3).","Menurut Pasal 24A ayat (3) UUD NRI 1945, jawabannya “Komisi Yudisial”, bukan “Mahkamah Agung”. MA mengadili pada tingkat kasasi dan menguji peraturan di bawah undang-undang terhadap undang-undang (Pasal 24A ayat 1).","DPR memberi persetujuan atas calon yang diusulkan Komisi Yudisial (Pasal 24A ayat 3).","Menurut Pasal 24A ayat (3) UUD NRI 1945, jawabannya “Komisi Yudisial”, bukan “Mahkamah Konstitusi”. MK menguji undang-undang terhadap UUD, memutus sengketa kewenangan lembaga negara, pembubaran partai politik, dan perselisihan hasil pemilu (Pasal 24C ayat 1).","Benar. Ini sesuai Pasal 24A ayat (3) UUD NRI 1945."],"h":"Urutannya: diusulkan, disetujui, lalu ditetapkan. Yang mengusulkan adalah lembaga yang dibentuk khusus untuk urusan pengangkatan dan perilaku hakim."},{"i":2815,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Lembaga yang berwenang menjaga dan menegakkan kehormatan, keluhuran martabat, serta perilaku hakim adalah …","e":"Pasal 24B ayat (1) UUD NRI 1945 berbunyi: “Komisi Yudisial bersifat mandiri yang berwenang mengusulkan pengangkatan hakim agung dan mempunyai wewenang lain dalam rangka menjaga dan menegakkan kehormatan, keluhuran martabat, serta perilaku hakim.”\nKomisi Yudisial bersifat mandiri dan juga berwenang mengusulkan pengangkatan hakim agung.\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Lembaga ini mengawasi perilaku hakim dari luar pengadilan, jadi bukan pengadilan itu sendiri.","o":["Dewan Perwakilan Rakyat","Kejaksaan Agung","Mahkamah Konstitusi","Mahkamah Agung","Komisi Yudisial"],"s":[0,0,0,0,1],"w":["Menurut Pasal 24B ayat (1) UUD NRI 1945, jawabannya “Komisi Yudisial”, bukan “Dewan Perwakilan Rakyat”. DPR memegang kekuasaan membentuk undang-undang (Pasal 20 ayat 1).","Menurut Pasal 24B ayat (1) UUD NRI 1945, jawabannya “Komisi Yudisial”, bukan “Kejaksaan Agung”.","Menurut Pasal 24B ayat (1) UUD NRI 1945, jawabannya “Komisi Yudisial”, bukan “Mahkamah Konstitusi”. MK menguji undang-undang terhadap UUD, memutus sengketa kewenangan lembaga negara, pembubaran partai politik, dan perselisihan hasil pemilu (Pasal 24C ayat 1).","Menurut Pasal 24B ayat (1) UUD NRI 1945, jawabannya “Komisi Yudisial”, bukan “Mahkamah Agung”. MA mengadili pada tingkat kasasi dan menguji peraturan di bawah undang-undang terhadap undang-undang (Pasal 24A ayat 1).","Benar. Ini sesuai Pasal 24B ayat (1) UUD NRI 1945."],"h":"Lembaga ini mengawasi perilaku hakim dari luar pengadilan, jadi bukan pengadilan itu sendiri."},{"i":2816,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Anggota Komisi Yudisial diangkat dan diberhentikan oleh …","e":"Pasal 24B ayat (3) UUD NRI 1945 berbunyi: “Anggota Komisi Yudisial diangkat dan diberhentikan oleh Presiden dengan persetujuan Dewan Perwakilan Rakyat.”\nKomisi Yudisial dibentuk lewat Perubahan Ketiga (2001).\nCara cepat: Pola pengisian jabatan semacam ini di UUD: kepala negara mengangkat, lembaga legislatif menyetujui. Cari pilihan yang urutannya seperti itu.","o":["Presiden atas usul Mahkamah Agung","Presiden dengan persetujuan Dewan Perwakilan Rakyat","Mahkamah Agung dengan persetujuan Dewan Perwakilan Rakyat","Dewan Perwakilan Rakyat dengan persetujuan Presiden","Majelis Permusyawaratan Rakyat"],"s":[0,1,0,0,0],"w":["Menurut Pasal 24B ayat (3) UUD NRI 1945, jawabannya “Presiden dengan persetujuan Dewan Perwakilan Rakyat”, bukan “Presiden atas usul Mahkamah Agung”.","Benar. Ini sesuai Pasal 24B ayat (3) UUD NRI 1945.","Menurut Pasal 24B ayat (3) UUD NRI 1945, jawabannya “Presiden dengan persetujuan Dewan Perwakilan Rakyat”, bukan “Mahkamah Agung dengan persetujuan Dewan Perwakilan Rakyat”.","Menurut Pasal 24B ayat (3) UUD NRI 1945, jawabannya “Presiden dengan persetujuan Dewan Perwakilan Rakyat”, bukan “Dewan Perwakilan Rakyat dengan persetujuan Presiden”.","Menurut Pasal 24B ayat (3) UUD NRI 1945, jawabannya “Presiden dengan persetujuan Dewan Perwakilan Rakyat”, bukan “Majelis Permusyawaratan Rakyat”. MPR berwenang mengubah dan menetapkan UUD (Pasal 3 ayat 1)."],"h":"Pola pengisian jabatan semacam ini di UUD: kepala negara mengangkat, lembaga legislatif menyetujui. Cari pilihan yang urutannya seperti itu."},{"i":2817,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Lembaga yang berwenang menguji undang-undang terhadap Undang-Undang Dasar adalah …","e":"Pasal 24C ayat (1) UUD NRI 1945 berbunyi: “Mahkamah Konstitusi berwenang mengadili pada tingkat pertama dan terakhir yang putusannya bersifat final untuk menguji undang-undang terhadap Undang-Undang Dasar, memutus sengketa kewenangan lembaga negara yang kewenangannya diberikan oleh Undang-Undang Dasar, memutus pembubaran partai politik, dan memutus perselisihan tentang hasil pemilihan umum.”\nPutusannya final: tidak ada upaya hukum lain sesudahnya. Bandingkan dengan MA, yang menguji peraturan di bawah UU terhadap UU.\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Batu ujinya UUD (konstitusi), jadi pengujinya lembaga yang namanya memuat kata 'konstitusi'.","o":["Mahkamah Agung","Komisi Yudisial","Dewan Perwakilan Rakyat","Mahkamah Konstitusi","Majelis Permusyawaratan Rakyat"],"s":[0,0,0,1,0],"w":["Menurut Pasal 24C ayat (1) UUD NRI 1945, jawabannya “Mahkamah Konstitusi”, bukan “Mahkamah Agung”. MA mengadili pada tingkat kasasi dan menguji peraturan di bawah undang-undang terhadap undang-undang (Pasal 24A ayat 1).","Menurut Pasal 24C ayat (1) UUD NRI 1945, jawabannya “Mahkamah Konstitusi”, bukan “Komisi Yudisial”. KY mengusulkan pengangkatan hakim agung dan menjaga kehormatan serta perilaku hakim (Pasal 24B ayat 1).","Menurut Pasal 24C ayat (1) UUD NRI 1945, jawabannya “Mahkamah Konstitusi”, bukan “Dewan Perwakilan Rakyat”. DPR memegang kekuasaan membentuk undang-undang (Pasal 20 ayat 1).","Benar. Ini sesuai Pasal 24C ayat (1) UUD NRI 1945.","Menurut Pasal 24C ayat (1) UUD NRI 1945, jawabannya “Mahkamah Konstitusi”, bukan “Majelis Permusyawaratan Rakyat”. MPR berwenang mengubah dan menetapkan UUD (Pasal 3 ayat 1)."],"h":"Batu ujinya UUD (konstitusi), jadi pengujinya lembaga yang namanya memuat kata 'konstitusi'."},{"i":2818,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Memutus pembubaran partai politik merupakan wewenang …","e":"Pasal 24C ayat (1) UUD NRI 1945 berbunyi: “Mahkamah Konstitusi berwenang mengadili pada tingkat pertama dan terakhir yang putusannya bersifat final untuk menguji undang-undang terhadap Undang-Undang Dasar, memutus sengketa kewenangan lembaga negara yang kewenangannya diberikan oleh Undang-Undang Dasar, memutus pembubaran partai politik, dan memutus perselisihan tentang hasil pemilihan umum.”\nPembubaran partai politik diputus Mahkamah Konstitusi, bukan oleh pemerintah atau KPU.\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Rumus empat wewenang peradilan konstitusi: 'UU, lembaga, partai, pemilu', yaitu menguji UU terhadap UUD, sengketa kewenangan lembaga negara, pembubaran partai politik, dan perselisihan hasil pemilu. Keempatnya milik satu lembaga yang sama.","o":["Komisi Pemilihan Umum","Mahkamah Agung","Dewan Perwakilan Rakyat","Mahkamah Konstitusi","Presiden"],"s":[0,0,0,1,0],"w":["Menurut Pasal 24C ayat (1) UUD NRI 1945, jawabannya “Mahkamah Konstitusi”, bukan “Komisi Pemilihan Umum”. Komisi pemilihan umum menyelenggarakan pemilu (Pasal 22E ayat 5).","Menurut Pasal 24C ayat (1) UUD NRI 1945, jawabannya “Mahkamah Konstitusi”, bukan “Mahkamah Agung”. MA mengadili pada tingkat kasasi dan menguji peraturan di bawah undang-undang terhadap undang-undang (Pasal 24A ayat 1).","Menurut Pasal 24C ayat (1) UUD NRI 1945, jawabannya “Mahkamah Konstitusi”, bukan “Dewan Perwakilan Rakyat”. DPR memegang kekuasaan membentuk undang-undang (Pasal 20 ayat 1).","Benar. Ini sesuai Pasal 24C ayat (1) UUD NRI 1945.","Menurut Pasal 24C ayat (1) UUD NRI 1945, jawabannya “Mahkamah Konstitusi”, bukan “Presiden”. Presiden memegang kekuasaan pemerintahan (Pasal 4 ayat 1)."],"h":"Rumus empat wewenang peradilan konstitusi: 'UU, lembaga, partai, pemilu', yaitu menguji UU terhadap UUD, sengketa kewenangan lembaga negara, pembubaran partai politik, dan perselisihan hasil pemilu. Keempatnya milik satu lembaga yang sama."},{"i":2819,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Memutus perselisihan tentang hasil pemilihan umum merupakan wewenang …","e":"Pasal 24C ayat (1) UUD NRI 1945 berbunyi: “Mahkamah Konstitusi berwenang mengadili pada tingkat pertama dan terakhir yang putusannya bersifat final untuk menguji undang-undang terhadap Undang-Undang Dasar, memutus sengketa kewenangan lembaga negara yang kewenangannya diberikan oleh Undang-Undang Dasar, memutus pembubaran partai politik, dan memutus perselisihan tentang hasil pemilihan umum.”\nKPU menetapkan hasil pemilu; bila hasil itu diperselisihkan, yang memutus Mahkamah Konstitusi.\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Rumus empat wewenang peradilan konstitusi: 'UU, lembaga, partai, pemilu', yaitu menguji UU terhadap UUD, sengketa kewenangan lembaga negara, pembubaran partai politik, dan perselisihan hasil pemilu. Keempatnya milik satu lembaga yang sama.","o":["Komisi Yudisial","Dewan Perwakilan Rakyat","Mahkamah Konstitusi","Mahkamah Agung","Komisi Pemilihan Umum"],"s":[0,0,1,0,0],"w":["Menurut Pasal 24C ayat (1) UUD NRI 1945, jawabannya “Mahkamah Konstitusi”, bukan “Komisi Yudisial”. KY mengusulkan pengangkatan hakim agung dan menjaga kehormatan serta perilaku hakim (Pasal 24B ayat 1).","Menurut Pasal 24C ayat (1) UUD NRI 1945, jawabannya “Mahkamah Konstitusi”, bukan “Dewan Perwakilan Rakyat”. DPR memegang kekuasaan membentuk undang-undang (Pasal 20 ayat 1).","Benar. Ini sesuai Pasal 24C ayat (1) UUD NRI 1945.","Menurut Pasal 24C ayat (1) UUD NRI 1945, jawabannya “Mahkamah Konstitusi”, bukan “Mahkamah Agung”. MA mengadili pada tingkat kasasi dan menguji peraturan di bawah undang-undang terhadap undang-undang (Pasal 24A ayat 1).","Menurut Pasal 24C ayat (1) UUD NRI 1945, jawabannya “Mahkamah Konstitusi”, bukan “Komisi Pemilihan Umum”. Komisi pemilihan umum menyelenggarakan pemilu (Pasal 22E ayat 5)."],"h":"Rumus empat wewenang peradilan konstitusi: 'UU, lembaga, partai, pemilu', yaitu menguji UU terhadap UUD, sengketa kewenangan lembaga negara, pembubaran partai politik, dan perselisihan hasil pemilu. Keempatnya milik satu lembaga yang sama."},{"i":2820,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Memutus sengketa kewenangan lembaga negara yang kewenangannya diberikan oleh UUD adalah wewenang …","e":"Pasal 24C ayat (1) UUD NRI 1945 berbunyi: “Mahkamah Konstitusi berwenang mengadili pada tingkat pertama dan terakhir yang putusannya bersifat final untuk menguji undang-undang terhadap Undang-Undang Dasar, memutus sengketa kewenangan lembaga negara yang kewenangannya diberikan oleh Undang-Undang Dasar, memutus pembubaran partai politik, dan memutus perselisihan tentang hasil pemilihan umum.”\nContohnya dua lembaga negara sama-sama merasa berwenang atas satu urusan yang diatur UUD.\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Rumus empat wewenang peradilan konstitusi: 'UU, lembaga, partai, pemilu', yaitu menguji UU terhadap UUD, sengketa kewenangan lembaga negara, pembubaran partai politik, dan perselisihan hasil pemilu. Keempatnya milik satu lembaga yang sama.","o":["Mahkamah Agung","Dewan Perwakilan Rakyat","Mahkamah Konstitusi","Majelis Permusyawaratan Rakyat","Presiden"],"s":[0,0,1,0,0],"w":["Menurut Pasal 24C ayat (1) UUD NRI 1945, jawabannya “Mahkamah Konstitusi”, bukan “Mahkamah Agung”. MA mengadili pada tingkat kasasi dan menguji peraturan di bawah undang-undang terhadap undang-undang (Pasal 24A ayat 1).","Menurut Pasal 24C ayat (1) UUD NRI 1945, jawabannya “Mahkamah Konstitusi”, bukan “Dewan Perwakilan Rakyat”. DPR memegang kekuasaan membentuk undang-undang (Pasal 20 ayat 1).","Benar. Ini sesuai Pasal 24C ayat (1) UUD NRI 1945.","Menurut Pasal 24C ayat (1) UUD NRI 1945, jawabannya “Mahkamah Konstitusi”, bukan “Majelis Permusyawaratan Rakyat”. MPR berwenang mengubah dan menetapkan UUD (Pasal 3 ayat 1).","Menurut Pasal 24C ayat (1) UUD NRI 1945, jawabannya “Mahkamah Konstitusi”, bukan “Presiden”. Presiden memegang kekuasaan pemerintahan (Pasal 4 ayat 1)."],"h":"Rumus empat wewenang peradilan konstitusi: 'UU, lembaga, partai, pemilu', yaitu menguji UU terhadap UUD, sengketa kewenangan lembaga negara, pembubaran partai politik, dan perselisihan hasil pemilu. Keempatnya milik satu lembaga yang sama."},{"i":2821,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Lembaga yang wajib memberikan putusan atas pendapat DPR mengenai dugaan pelanggaran oleh Presiden dan/atau Wakil Presiden adalah …","e":"Pasal 24C ayat (2) UUD NRI 1945 berbunyi: “Mahkamah Konstitusi wajib memberikan putusan atas pendapat Dewan Perwakilan Rakyat mengenai dugaan pelanggaran oleh Presiden dan/atau Wakil Presiden menurut Undang-Undang Dasar.”\nAlurnya diatur Pasal 7B: DPR, lalu MK (paling lama 90 hari), lalu DPR meneruskan usul, lalu MPR (paling lambat 30 hari).\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Pemberhentian Presiden melewati tiga lembaga: DPR berpendapat, peradilan konstitusi memutus secara hukum, lalu MPR memutus secara politik.","o":["Majelis Permusyawaratan Rakyat","Mahkamah Konstitusi","Komisi Yudisial","Mahkamah Agung","Dewan Perwakilan Daerah"],"s":[0,1,0,0,0],"w":["MPR memutus usul pemberhentian yang diteruskan DPR setelah ada putusan MK (Pasal 7B ayat 5 dan 6).","Benar. Ini sesuai Pasal 24C ayat (2) UUD NRI 1945.","Menurut Pasal 24C ayat (2) UUD NRI 1945, jawabannya “Mahkamah Konstitusi”, bukan “Komisi Yudisial”. KY mengusulkan pengangkatan hakim agung dan menjaga kehormatan serta perilaku hakim (Pasal 24B ayat 1).","Menurut Pasal 24C ayat (2) UUD NRI 1945, jawabannya “Mahkamah Konstitusi”, bukan “Mahkamah Agung”. MA mengadili pada tingkat kasasi dan menguji peraturan di bawah undang-undang terhadap undang-undang (Pasal 24A ayat 1).","Menurut Pasal 24C ayat (2) UUD NRI 1945, jawabannya “Mahkamah Konstitusi”, bukan “Dewan Perwakilan Daerah”. DPD dapat mengajukan dan ikut membahas RUU tertentu, misalnya yang berkaitan dengan otonomi daerah (Pasal 22D)."],"h":"Pemberhentian Presiden melewati tiga lembaga: DPR berpendapat, peradilan konstitusi memutus secara hukum, lalu MPR memutus secara politik."},{"i":2822,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Ketua dan Wakil Ketua Mahkamah Konstitusi dipilih …","e":"Pasal 24C ayat (4) UUD NRI 1945 berbunyi: “Ketua dan Wakil Ketua Mahkamah Konstitusi dipilih dari dan oleh hakim konstitusi.”\nPolanya sama dengan Mahkamah Agung (Pasal 24A ayat 4) dan BPK (Pasal 23F ayat 2).\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Pimpinan lembaga peradilan dan BPK dipilih secara internal, dari dan oleh anggotanya sendiri.","o":["dari dan oleh hakim konstitusi","oleh Dewan Perwakilan Rakyat","oleh Majelis Permusyawaratan Rakyat","dari hakim konstitusi oleh Mahkamah Agung","oleh Presiden"],"s":[1,0,0,0,0],"w":["Benar. Ini sesuai Pasal 24C ayat (4) UUD NRI 1945.","Menurut Pasal 24C ayat (4) UUD NRI 1945, jawabannya “dari dan oleh hakim konstitusi”, bukan “oleh Dewan Perwakilan Rakyat”.","Menurut Pasal 24C ayat (4) UUD NRI 1945, jawabannya “dari dan oleh hakim konstitusi”, bukan “oleh Majelis Permusyawaratan Rakyat”. “oleh Majelis Permusyawaratan Rakyat” ada di ketentuan lain, Pasal 7A UUD NRI 1945: “Presiden dan/atau Wakil Presiden dapat diberhentikan dalam masa jabatannya oleh Majelis Permusyawaratan Rakyat atas usul Dewan Perwakilan Rakyat, baik apabila terbukti telah melakukan…”","Menurut Pasal 24C ayat (4) UUD NRI 1945, jawabannya “dari dan oleh hakim konstitusi”, bukan “dari hakim konstitusi oleh Mahkamah Agung”.","Menurut Pasal 24C ayat (4) UUD NRI 1945, jawabannya “dari dan oleh hakim konstitusi”, bukan “oleh Presiden”."],"h":"Pimpinan lembaga peradilan dan BPK dipilih secara internal, dari dan oleh anggotanya sendiri."},{"i":2823,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Presiden dan/atau Wakil Presiden dapat diberhentikan dalam masa jabatannya oleh …","e":"Pasal 7A UUD NRI 1945 berbunyi: “Presiden dan/atau Wakil Presiden dapat diberhentikan dalam masa jabatannya oleh Majelis Permusyawaratan Rakyat atas usul Dewan Perwakilan Rakyat, baik apabila terbukti telah melakukan pelanggaran hukum berupa pengkhianatan terhadap negara, korupsi, penyuapan, tindak pidana berat lainnya, atau perbuatan tercela maupun apabila terbukti tidak lagi memenuhi syarat sebagai Presiden dan/atau Wakil Presiden.”\nSebelum usul sampai ke MPR, DPR harus lebih dulu meminta Mahkamah Konstitusi memeriksa dan memutus pendapatnya (Pasal 7B ayat 1).\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Lembaga yang melantik juga yang memberhentikan; usulnya datang dari lembaga yang menjalankan fungsi pengawasan.","o":["Majelis Permusyawaratan Rakyat atas usul Dewan Perwakilan Rakyat","Mahkamah Konstitusi atas usul Dewan Perwakilan Rakyat","Mahkamah Agung atas usul Dewan Perwakilan Daerah","Dewan Perwakilan Rakyat atas putusan Mahkamah Agung","Dewan Perwakilan Rakyat atas usul Majelis Permusyawaratan Rakyat"],"s":[1,0,0,0,0],"w":["Benar. Ini sesuai Pasal 7A UUD NRI 1945.","Menurut Pasal 7A UUD NRI 1945, jawabannya “Majelis Permusyawaratan Rakyat atas usul Dewan Perwakilan Rakyat”, bukan “Mahkamah Konstitusi atas usul Dewan Perwakilan Rakyat”.","Menurut Pasal 7A UUD NRI 1945, jawabannya “Majelis Permusyawaratan Rakyat atas usul Dewan Perwakilan Rakyat”, bukan “Mahkamah Agung atas usul Dewan Perwakilan Daerah”.","Menurut Pasal 7A UUD NRI 1945, jawabannya “Majelis Permusyawaratan Rakyat atas usul Dewan Perwakilan Rakyat”, bukan “Dewan Perwakilan Rakyat atas putusan Mahkamah Agung”.","Menurut Pasal 7A UUD NRI 1945, jawabannya “Majelis Permusyawaratan Rakyat atas usul Dewan Perwakilan Rakyat”, bukan “Dewan Perwakilan Rakyat atas usul Majelis Permusyawaratan Rakyat”."],"h":"Lembaga yang melantik juga yang memberhentikan; usulnya datang dari lembaga yang menjalankan fungsi pengawasan."},{"i":2824,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Jika Presiden mangkat, berhenti, diberhentikan, atau tidak dapat melakukan kewajibannya dalam masa jabatannya, ia digantikan oleh …","e":"Pasal 8 ayat (1) UUD NRI 1945 berbunyi: “Jika Presiden mangkat, berhenti, diberhentikan, atau tidak dapat melakukan kewajibannya dalam masa jabatannya, ia digantikan oleh Wakil Presiden sampai habis masa jabatannya.”\nWakil Presiden menggantikan sampai habis masa jabatannya.\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Kalau hanya Presiden yang berhalangan, penggantinya orang kedua di eksekutif. Tiga menteri baru bertugas bila kedua pemimpin eksekutif berhalangan bersamaan.","o":["Menteri Luar Negeri, Menteri Dalam Negeri, dan Menteri Pertahanan","Wakil Presiden","Menteri Dalam Negeri","Ketua Dewan Perwakilan Rakyat","Ketua Majelis Permusyawaratan Rakyat"],"s":[0,1,0,0,0],"w":["Menurut Pasal 8 ayat (1) UUD NRI 1945, jawabannya “Wakil Presiden”, bukan “Menteri Luar Negeri, Menteri Dalam Negeri, dan Menteri Pertahanan”. “Menteri Luar Negeri, Menteri Dalam Negeri, dan Menteri Pertahanan” ada di ketentuan lain, Pasal 8 ayat (3) UUD NRI 1945: “…masa jabatannya secara bersamaan, pelaksana tugas kepresidenan adalah Menteri Luar Negeri, Menteri Dalam Negeri, dan Menteri Pertahanan secara bersamasama. Selambat-lambatnya tiga puluh hari setelah itu, Majelis…”","Benar. Ini sesuai Pasal 8 ayat (1) UUD NRI 1945.","Menurut Pasal 8 ayat (1) UUD NRI 1945, jawabannya “Wakil Presiden”, bukan “Menteri Dalam Negeri”. “Menteri Dalam Negeri” ada di ketentuan lain, Pasal 8 ayat (3) UUD NRI 1945: “…secara bersamaan, pelaksana tugas kepresidenan adalah Menteri Luar Negeri, Menteri Dalam Negeri, dan Menteri Pertahanan secara bersamasama. Selambat-lambatnya tiga puluh…”","Menurut Pasal 8 ayat (1) UUD NRI 1945, jawabannya “Wakil Presiden”, bukan “Ketua Dewan Perwakilan Rakyat”.","Menurut Pasal 8 ayat (1) UUD NRI 1945, jawabannya “Wakil Presiden”, bukan “Ketua Majelis Permusyawaratan Rakyat”."],"h":"Kalau hanya Presiden yang berhalangan, penggantinya orang kedua di eksekutif. Tiga menteri baru bertugas bila kedua pemimpin eksekutif berhalangan bersamaan."},{"i":2825,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Jika Presiden dan Wakil Presiden berhalangan tetap secara bersamaan, pelaksana tugas kepresidenan adalah …","e":"Pasal 8 ayat (3) UUD NRI 1945 berbunyi: “Jika Presiden dan Wakil Presiden mangkat, berhenti, diberhentikan atau tidak dapat melakukan kewajibannya dalam masa jabatannya secara bersamaan, pelaksana tugas kepresidenan adalah Menteri Luar Negeri, Menteri Dalam Negeri, dan Menteri Pertahanan secara bersamasama. Selambat-lambatnya tiga puluh hari setelah itu, Majelis Permusyawaratan Rakyat menyelenggarakan sidang untuk memilih Presiden dan Wakil Presiden dari dua pasangan calon Presiden dan Wakil Presiden yang diusulkan oleh partai politik yang pasangan calon Presiden dan Wakil Presidennya meraih suara terbanyak pertama dan kedua dalam pemilihan umum sebelumnya, sampai akhir masa jabatannya.”\nPaling lambat 30 hari kemudian MPR bersidang memilih Presiden dan Wakil Presiden dari dua pasangan calon yang diusulkan partai politik peraih suara terbanyak pertama dan kedua pada pemilu sebelumnya.\nAyat ini dirumuskan dalam Perubahan Keempat (2002).\nCara cepat: Ingat LDP: Luar negeri, Dalam negeri, Pertahanan, yaitu tiga urusan yang menjaga negara tetap berjalan.","o":["Menteri Sekretaris Negara dan Menteri Dalam Negeri","Menteri Dalam Negeri, Menteri Keuangan, dan Panglima TNI","Ketua Mahkamah Agung dan Ketua Mahkamah Konstitusi","Ketua MPR, Ketua DPR, dan Ketua DPD secara bersama-sama","Menteri Luar Negeri, Menteri Dalam Negeri, dan Menteri Pertahanan secara bersama-sama"],"s":[0,0,0,0,1],"w":["Menurut Pasal 8 ayat (3) UUD NRI 1945, jawabannya “Menteri Luar Negeri, Menteri Dalam Negeri, dan Menteri Pertahanan secara bersama-sama”, bukan “Menteri Sekretaris Negara dan Menteri Dalam Negeri”.","Menurut Pasal 8 ayat (3) UUD NRI 1945, jawabannya “Menteri Luar Negeri, Menteri Dalam Negeri, dan Menteri Pertahanan secara bersama-sama”, bukan “Menteri Dalam Negeri, Menteri Keuangan, dan Panglima TNI”.","Menurut Pasal 8 ayat (3) UUD NRI 1945, jawabannya “Menteri Luar Negeri, Menteri Dalam Negeri, dan Menteri Pertahanan secara bersama-sama”, bukan “Ketua Mahkamah Agung dan Ketua Mahkamah Konstitusi”.","Menurut Pasal 8 ayat (3) UUD NRI 1945, jawabannya “Menteri Luar Negeri, Menteri Dalam Negeri, dan Menteri Pertahanan secara bersama-sama”, bukan “Ketua MPR, Ketua DPR, dan Ketua DPD secara bersama-sama”.","Benar. Ini sesuai Pasal 8 ayat (3) UUD NRI 1945."],"h":"Ingat LDP: Luar negeri, Dalam negeri, Pertahanan, yaitu tiga urusan yang menjaga negara tetap berjalan."},{"i":2826,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Dalam hal ihwal kegentingan yang memaksa, Presiden berhak menetapkan …","e":"Pasal 22 ayat (1) UUD NRI 1945 berbunyi: “Dalam hal ihwal kegentingan yang memaksa, Presiden berhak menetapkan peraturan pemerintah sebagai pengganti undang-undang.”\nPerpu harus mendapat persetujuan DPR dalam persidangan berikutnya; kalau tidak disetujui, perpu harus dicabut (Pasal 22 ayat 2 dan 3).\nBunyi ini sudah ada sejak naskah asli UUD 1945.\nCara cepat: Kegentingan butuh aturan setingkat undang-undang secara cepat; namanya mengandung kata 'pengganti undang-undang' (perpu).","o":["keputusan presiden","undang-undang darurat","peraturan presiden","dekret presiden","peraturan pemerintah sebagai pengganti undang-undang"],"s":[0,0,0,0,1],"w":["Menurut Pasal 22 ayat (1) UUD NRI 1945, jawabannya “peraturan pemerintah sebagai pengganti undang-undang”, bukan “keputusan presiden”.","Menurut Pasal 22 ayat (1) UUD NRI 1945, jawabannya “peraturan pemerintah sebagai pengganti undang-undang”, bukan “undang-undang darurat”.","Menurut Pasal 22 ayat (1) UUD NRI 1945, jawabannya “peraturan pemerintah sebagai pengganti undang-undang”, bukan “peraturan presiden”.","Menurut Pasal 22 ayat (1) UUD NRI 1945, jawabannya “peraturan pemerintah sebagai pengganti undang-undang”, bukan “dekret presiden”.","Benar. Ini sesuai Pasal 22 ayat (1) UUD NRI 1945."],"h":"Kegentingan butuh aturan setingkat undang-undang secara cepat; namanya mengandung kata 'pengganti undang-undang' (perpu)."},{"i":2827,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Peraturan pemerintah sebagai pengganti undang-undang harus mendapat persetujuan … dalam persidangan yang berikut.","e":"Pasal 22 ayat (2) UUD NRI 1945 berbunyi: “Peraturan pemerintah itu harus mendapat persetujuan Dewan Perwakilan Rakyat dalam persidangan yang berikut.”\nJika tidak mendapat persetujuan, perpu itu harus dicabut (Pasal 22 ayat 3).\nBunyi ini sudah ada sejak naskah asli UUD 1945.\nCara cepat: Perpu setingkat undang-undang, jadi yang menyetujui lembaga pemegang kekuasaan membentuk undang-undang.","o":["Mahkamah Agung","Dewan Perwakilan Daerah","Majelis Permusyawaratan Rakyat","Mahkamah Konstitusi","Dewan Perwakilan Rakyat"],"s":[0,0,0,0,1],"w":["Menurut Pasal 22 ayat (2) UUD NRI 1945, jawabannya “Dewan Perwakilan Rakyat”, bukan “Mahkamah Agung”. MA mengadili pada tingkat kasasi dan menguji peraturan di bawah undang-undang terhadap undang-undang (Pasal 24A ayat 1).","Menurut Pasal 22 ayat (2) UUD NRI 1945, jawabannya “Dewan Perwakilan Rakyat”, bukan “Dewan Perwakilan Daerah”. DPD dapat mengajukan dan ikut membahas RUU tertentu, misalnya yang berkaitan dengan otonomi daerah (Pasal 22D).","Menurut Pasal 22 ayat (2) UUD NRI 1945, jawabannya “Dewan Perwakilan Rakyat”, bukan “Majelis Permusyawaratan Rakyat”. MPR berwenang mengubah dan menetapkan UUD (Pasal 3 ayat 1).","Menurut Pasal 22 ayat (2) UUD NRI 1945, jawabannya “Dewan Perwakilan Rakyat”, bukan “Mahkamah Konstitusi”. MK menguji undang-undang terhadap UUD, memutus sengketa kewenangan lembaga negara, pembubaran partai politik, dan perselisihan hasil pemilu (Pasal 24C ayat 1).","Benar. Ini sesuai Pasal 22 ayat (2) UUD NRI 1945."],"h":"Perpu setingkat undang-undang, jadi yang menyetujui lembaga pemegang kekuasaan membentuk undang-undang."},{"i":2828,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Rancangan undang-undang anggaran pendapatan dan belanja negara diajukan oleh …","e":"Pasal 23 ayat (2) UUD NRI 1945 berbunyi: “Rancangan undang-undang anggaran pendapatan dan belanja negara diajukan oleh Presiden untuk dibahas bersama Dewan Perwakilan Rakyat dengan memperhatikan pertimbangan Dewan Perwakilan Daerah.”\nRAPBN dibahas bersama DPR dengan memperhatikan pertimbangan DPD. Bila DPR tidak menyetujui, Pemerintah menjalankan APBN tahun lalu (Pasal 23 ayat 3).\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Yang menjalankan anggaran adalah pemerintah, jadi rancangannya datang dari kepala pemerintahan; DPR membahas dan menyetujui.","o":["Dewan Perwakilan Rakyat","Badan Pemeriksa Keuangan","Dewan Perwakilan Daerah","Menteri Keuangan","Presiden"],"s":[0,0,0,0,1],"w":["Menurut Pasal 23 ayat (2) UUD NRI 1945, jawabannya “Presiden”, bukan “Dewan Perwakilan Rakyat”. DPR memegang kekuasaan membentuk undang-undang (Pasal 20 ayat 1).","Menurut Pasal 23 ayat (2) UUD NRI 1945, jawabannya “Presiden”, bukan “Badan Pemeriksa Keuangan”. BPK memeriksa pengelolaan dan tanggung jawab keuangan negara (Pasal 23E ayat 1).","Menurut Pasal 23 ayat (2) UUD NRI 1945, jawabannya “Presiden”, bukan “Dewan Perwakilan Daerah”. DPD dapat mengajukan dan ikut membahas RUU tertentu, misalnya yang berkaitan dengan otonomi daerah (Pasal 22D).","Menurut Pasal 23 ayat (2) UUD NRI 1945, jawabannya “Presiden”, bukan “Menteri Keuangan”.","Benar. Ini sesuai Pasal 23 ayat (2) UUD NRI 1945."],"h":"Yang menjalankan anggaran adalah pemerintah, jadi rancangannya datang dari kepala pemerintahan; DPR membahas dan menyetujui."},{"i":2829,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Pasangan calon Presiden dan Wakil Presiden diusulkan oleh …","e":"Pasal 6A ayat (2) UUD NRI 1945 berbunyi: “Pasangan calon Presiden dan Wakil Presiden diusulkan oleh partai politik atau gabungan partai politik peserta pemilihan umum sebelum pelaksanaan pemilihan umum.”\nUsul diajukan sebelum pemilihan umum dilaksanakan.\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Peserta pemilu perseorangan hanya ada untuk pemilu anggota DPD (Pasal 22E ayat 4). Untuk pemilihan Presiden, pengusulnya peserta pemilu yang berbentuk organisasi politik.","o":["partai politik atau gabungan partai politik peserta pemilihan umum","Dewan Perwakilan Rakyat","Komisi Pemilihan Umum","perseorangan dengan dukungan tanda tangan rakyat","Majelis Permusyawaratan Rakyat"],"s":[1,0,0,0,0],"w":["Benar. Ini sesuai Pasal 6A ayat (2) UUD NRI 1945.","Menurut Pasal 6A ayat (2) UUD NRI 1945, jawabannya “partai politik atau gabungan partai politik peserta pemilihan umum”, bukan “Dewan Perwakilan Rakyat”. DPR memegang kekuasaan membentuk undang-undang (Pasal 20 ayat 1).","Menurut Pasal 6A ayat (2) UUD NRI 1945, jawabannya “partai politik atau gabungan partai politik peserta pemilihan umum”, bukan “Komisi Pemilihan Umum”. Komisi pemilihan umum menyelenggarakan pemilu (Pasal 22E ayat 5).","Menurut Pasal 6A ayat (2) UUD NRI 1945, jawabannya “partai politik atau gabungan partai politik peserta pemilihan umum”, bukan “perseorangan dengan dukungan tanda tangan rakyat”.","Menurut Pasal 6A ayat (2) UUD NRI 1945, jawabannya “partai politik atau gabungan partai politik peserta pemilihan umum”, bukan “Majelis Permusyawaratan Rakyat”. MPR berwenang mengubah dan menetapkan UUD (Pasal 3 ayat 1)."],"h":"Peserta pemilu perseorangan hanya ada untuk pemilu anggota DPD (Pasal 22E ayat 4). Untuk pemilihan Presiden, pengusulnya peserta pemilu yang berbentuk organisasi politik."},{"i":2830,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Menurut UUD NRI 1945 setelah perubahan, Presiden dan Wakil Presiden dipilih …","e":"Pasal 6A ayat (1) UUD NRI 1945 berbunyi: “Presiden dan Wakil Presiden dipilih dalam satu pasangan secara langsung oleh rakyat.”\nSebelum perubahan, Presiden dan Wakil Presiden dipilih oleh MPR dengan suara terbanyak (naskah asli Pasal 6 ayat 2).\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Sejak Perubahan Ketiga (2001) Presiden tidak lagi dipilih MPR. Ada dua kata kunci: berpasangan dan tanpa perantara.","o":["oleh Dewan Perwakilan Rakyat dan Dewan Perwakilan Daerah","oleh MPR atas usul partai politik","oleh Majelis Permusyawaratan Rakyat dengan suara terbanyak","dalam satu pasangan secara langsung oleh rakyat","secara terpisah oleh rakyat"],"s":[0,0,0,1,0],"w":["Menurut Pasal 6A ayat (1) UUD NRI 1945, jawabannya “dalam satu pasangan secara langsung oleh rakyat”, bukan “oleh Dewan Perwakilan Rakyat dan Dewan Perwakilan Daerah”.","Menurut Pasal 6A ayat (1) UUD NRI 1945, jawabannya “dalam satu pasangan secara langsung oleh rakyat”, bukan “oleh MPR atas usul partai politik”.","Menurut Pasal 6A ayat (1) UUD NRI 1945, jawabannya “dalam satu pasangan secara langsung oleh rakyat”, bukan “oleh Majelis Permusyawaratan Rakyat dengan suara terbanyak”.","Benar. Ini sesuai Pasal 6A ayat (1) UUD NRI 1945.","Menurut Pasal 6A ayat (1) UUD NRI 1945, jawabannya “dalam satu pasangan secara langsung oleh rakyat”, bukan “secara terpisah oleh rakyat”."],"h":"Sejak Perubahan Ketiga (2001) Presiden tidak lagi dipilih MPR. Ada dua kata kunci: berpasangan dan tanpa perantara."},{"i":2831,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Peserta pemilihan umum untuk memilih anggota DPR dan anggota DPRD adalah …","e":"Pasal 22E ayat (3) UUD NRI 1945 berbunyi: “Peserta pemilihan umum untuk memilih anggota Dewan Perwakilan Rakyat dan anggota Dewan Perwakilan Rakyat Daerah adalah partai politik.”\nBandingkan Pasal 22E ayat (4): peserta pemilu anggota DPD adalah perseorangan.\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: DPR dan DPRD mewakili rakyat lewat organisasi politik; DPD mewakili daerah lewat tokoh perseorangan.","o":["Komisi Pemilihan Umum","organisasi kemasyarakatan","perseorangan","gabungan partai politik dan perseorangan","partai politik"],"s":[0,0,0,0,1],"w":["Menurut Pasal 22E ayat (3) UUD NRI 1945, jawabannya “partai politik”, bukan “Komisi Pemilihan Umum”. Komisi pemilihan umum menyelenggarakan pemilu (Pasal 22E ayat 5).","Menurut Pasal 22E ayat (3) UUD NRI 1945, jawabannya “partai politik”, bukan “organisasi kemasyarakatan”.","Menurut Pasal 22E ayat (3) UUD NRI 1945, jawabannya “partai politik”, bukan “perseorangan”.","Menurut Pasal 22E ayat (3) UUD NRI 1945, jawabannya “partai politik”, bukan “gabungan partai politik dan perseorangan”.","Benar. Ini sesuai Pasal 22E ayat (3) UUD NRI 1945."],"h":"DPR dan DPRD mewakili rakyat lewat organisasi politik; DPD mewakili daerah lewat tokoh perseorangan."},{"i":2832,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Peserta pemilihan umum untuk memilih anggota Dewan Perwakilan Daerah adalah …","e":"Pasal 22E ayat (4) UUD NRI 1945 berbunyi: “Peserta pemilihan umum untuk memilih anggota Dewan Perwakilan Daerah adalah perseorangan.”\nAnggota DPD dipilih dari setiap provinsi melalui pemilu (Pasal 22C ayat 1).\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: DPR dan DPRD mewakili rakyat lewat organisasi politik; DPD mewakili daerah lewat tokoh, bukan organisasi.","o":["utusan pemerintah daerah","partai politik","organisasi kemasyarakatan","perseorangan","gabungan partai politik"],"s":[0,0,0,1,0],"w":["Menurut Pasal 22E ayat (4) UUD NRI 1945, jawabannya “perseorangan”, bukan “utusan pemerintah daerah”.","Menurut Pasal 22E ayat (4) UUD NRI 1945, jawabannya “perseorangan”, bukan “partai politik”.","Menurut Pasal 22E ayat (4) UUD NRI 1945, jawabannya “perseorangan”, bukan “organisasi kemasyarakatan”.","Benar. Ini sesuai Pasal 22E ayat (4) UUD NRI 1945.","Menurut Pasal 22E ayat (4) UUD NRI 1945, jawabannya “perseorangan”, bukan “gabungan partai politik”. “gabungan partai politik” ada di ketentuan lain, Pasal 6A ayat (2) UUD NRI 1945: “Pasangan calon Presiden dan Wakil Presiden diusulkan oleh partai politik atau gabungan partai politik peserta pemilihan umum sebelum pelaksanaan pemilihan umum.”"],"h":"DPR dan DPRD mewakili rakyat lewat organisasi politik; DPD mewakili daerah lewat tokoh, bukan organisasi."},{"i":2833,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Alat negara yang bertugas mempertahankan, melindungi, dan memelihara keutuhan dan kedaulatan negara adalah …","e":"Pasal 30 ayat (3) UUD NRI 1945 berbunyi: “Tentara Nasional Indonesia terdiri atas Angkatan Darat, Angkatan Laut dan Angkatan Udara sebagai alat negara bertugas mempertahankan, melindungi, dan memelihara keutuhan dan kedaulatan negara.”\nBandingkan Pasal 30 ayat (4): Kepolisian menjaga keamanan dan ketertiban masyarakat, melindungi, mengayomi, melayani, dan menegakkan hukum.\nAyat ini dirumuskan dalam Perubahan Kedua (2000).\nCara cepat: Keutuhan dan kedaulatan negara adalah urusan pertahanan, jadi tugas angkatan bersenjata. Keamanan dan ketertiban masyarakat urusan kepolisian.","o":["Kepolisian Negara Republik Indonesia","Badan Nasional Penanggulangan Bencana","Badan Intelijen Negara","Badan Pemeriksa Keuangan","Tentara Nasional Indonesia"],"s":[0,0,0,0,1],"w":["Menurut Pasal 30 ayat (3) UUD NRI 1945, jawabannya “Tentara Nasional Indonesia”, bukan “Kepolisian Negara Republik Indonesia”. “Kepolisian Negara Republik Indonesia” ada di ketentuan lain, Pasal 30 ayat (4) UUD NRI 1945: “Kepolisian Negara Republik Indonesia sebagai alat negara yang menjaga keamanan dan ketertiban masyarakat bertugas…”","Menurut Pasal 30 ayat (3) UUD NRI 1945, jawabannya “Tentara Nasional Indonesia”, bukan “Badan Nasional Penanggulangan Bencana”.","Menurut Pasal 30 ayat (3) UUD NRI 1945, jawabannya “Tentara Nasional Indonesia”, bukan “Badan Intelijen Negara”.","Menurut Pasal 30 ayat (3) UUD NRI 1945, jawabannya “Tentara Nasional Indonesia”, bukan “Badan Pemeriksa Keuangan”. BPK memeriksa pengelolaan dan tanggung jawab keuangan negara (Pasal 23E ayat 1).","Benar. Ini sesuai Pasal 30 ayat (3) UUD NRI 1945."],"h":"Keutuhan dan kedaulatan negara adalah urusan pertahanan, jadi tugas angkatan bersenjata. Keamanan dan ketertiban masyarakat urusan kepolisian."},{"i":2834,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Alat negara yang menjaga keamanan dan ketertiban masyarakat serta bertugas melindungi, mengayomi, melayani masyarakat, dan menegakkan hukum adalah …","e":"Pasal 30 ayat (4) UUD NRI 1945 berbunyi: “Kepolisian Negara Republik Indonesia sebagai alat negara yang menjaga keamanan dan ketertiban masyarakat bertugas melindungi, mengayomi, melayani masyarakat, serta menegakkan hukum.”\nBandingkan Pasal 30 ayat (3): TNI mempertahankan, melindungi, dan memelihara keutuhan dan kedaulatan negara.\nAyat ini dirumuskan dalam Perubahan Kedua (2000).\nCara cepat: Keamanan dan ketertiban masyarakat sehari-hari serta penegakan hukum adalah tugas polisi; pertahanan negara tugas tentara.","o":["Kepolisian Negara Republik Indonesia","Badan Nasional Penanggulangan Bencana","Badan Pemeriksa Keuangan","Badan Intelijen Negara","Tentara Nasional Indonesia"],"s":[1,0,0,0,0],"w":["Benar. Ini sesuai Pasal 30 ayat (4) UUD NRI 1945.","Menurut Pasal 30 ayat (4) UUD NRI 1945, jawabannya “Kepolisian Negara Republik Indonesia”, bukan “Badan Nasional Penanggulangan Bencana”.","Menurut Pasal 30 ayat (4) UUD NRI 1945, jawabannya “Kepolisian Negara Republik Indonesia”, bukan “Badan Pemeriksa Keuangan”. BPK memeriksa pengelolaan dan tanggung jawab keuangan negara (Pasal 23E ayat 1).","Menurut Pasal 30 ayat (4) UUD NRI 1945, jawabannya “Kepolisian Negara Republik Indonesia”, bukan “Badan Intelijen Negara”.","Menurut Pasal 30 ayat (4) UUD NRI 1945, jawabannya “Kepolisian Negara Republik Indonesia”, bukan “Tentara Nasional Indonesia”."],"h":"Keamanan dan ketertiban masyarakat sehari-hari serta penegakan hukum adalah tugas polisi; pertahanan negara tugas tentara."},{"i":2835,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Usaha pertahanan dan keamanan negara dilaksanakan melalui …","e":"Pasal 30 ayat (2) UUD NRI 1945 berbunyi: “Usaha pertahanan dan keamanan negara dilaksanakan melalui sistem pertahanan dan keamanan rakyat semesta oleh Tentara Nasional Indonesia dan Kepolisian Negara Indonesia Republik Indonesia, sebagai kekuatan utama, dan rakyat, sebagai kekuatan pendukung.”\nTNI dan Kepolisian sebagai kekuatan utama, dan rakyat sebagai kekuatan pendukung.\nAyat ini dirumuskan dalam Perubahan Kedua (2000).\nCara cepat: Kata kuncinya 'semesta': seluruh rakyat terlibat. TNI dan Polri kekuatan utama, rakyat kekuatan pendukung.","o":["sistem keamanan swakarsa","sistem pertahanan dan keamanan rakyat semesta","sistem pertahanan aktif nonblok","sistem pertahanan berlapis antarnegara","sistem wajib militer bagi seluruh warga"],"s":[0,1,0,0,0],"w":["Menurut Pasal 30 ayat (2) UUD NRI 1945, jawabannya “sistem pertahanan dan keamanan rakyat semesta”, bukan “sistem keamanan swakarsa”.","Benar. Ini sesuai Pasal 30 ayat (2) UUD NRI 1945.","Menurut Pasal 30 ayat (2) UUD NRI 1945, jawabannya “sistem pertahanan dan keamanan rakyat semesta”, bukan “sistem pertahanan aktif nonblok”.","Menurut Pasal 30 ayat (2) UUD NRI 1945, jawabannya “sistem pertahanan dan keamanan rakyat semesta”, bukan “sistem pertahanan berlapis antarnegara”.","Menurut Pasal 30 ayat (2) UUD NRI 1945, jawabannya “sistem pertahanan dan keamanan rakyat semesta”, bukan “sistem wajib militer bagi seluruh warga”."],"h":"Kata kuncinya 'semesta': seluruh rakyat terlibat. TNI dan Polri kekuatan utama, rakyat kekuatan pendukung."},{"i":2836,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Menurut UUD NRI 1945, gubernur, bupati, dan wali kota sebagai kepala pemerintah daerah …","e":"Pasal 18 ayat (4) UUD NRI 1945 berbunyi: “Gubernur, Bupati dan Walikota masing-masing sebagai Kepala Pemerintah Daerah Provinsi, Kabupaten dan Kota dipilih secara demokratis.”\nCara pemilihannya, langsung oleh rakyat atau tidak, diatur undang-undang.\nAyat ini dirumuskan dalam Perubahan Kedua (2000).\nCara cepat: UUD tidak memakai kata 'langsung' untuk kepala daerah. Kata itu khusus untuk pemilihan Presiden (Pasal 6A).","o":["dipilih oleh Dewan Perwakilan Daerah","ditunjuk oleh Menteri Dalam Negeri","diangkat oleh Presiden","dipilih oleh Majelis Permusyawaratan Rakyat","dipilih secara demokratis"],"s":[0,0,0,0,1],"w":["Menurut Pasal 18 ayat (4) UUD NRI 1945, jawabannya “dipilih secara demokratis”, bukan “dipilih oleh Dewan Perwakilan Daerah”.","Menurut Pasal 18 ayat (4) UUD NRI 1945, jawabannya “dipilih secara demokratis”, bukan “ditunjuk oleh Menteri Dalam Negeri”.","Menurut Pasal 18 ayat (4) UUD NRI 1945, jawabannya “dipilih secara demokratis”, bukan “diangkat oleh Presiden”.","Menurut Pasal 18 ayat (4) UUD NRI 1945, jawabannya “dipilih secara demokratis”, bukan “dipilih oleh Majelis Permusyawaratan Rakyat”.","Benar. Ini sesuai Pasal 18 ayat (4) UUD NRI 1945."],"h":"UUD tidak memakai kata 'langsung' untuk kepala daerah. Kata itu khusus untuk pemilihan Presiden (Pasal 6A)."},{"i":2837,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Pemerintahan daerah mengatur dan mengurus sendiri urusan pemerintahan menurut asas …","e":"Pasal 18 ayat (2) UUD NRI 1945 berbunyi: “Pemerintahan daerah provinsi, daerah kabupaten, dan kota mengatur dan mengurus sendiri urusan pemerintahan menurut asas otonomi dan tugas pembantuan.”\nOtonominya seluas-luasnya, kecuali urusan yang oleh undang-undang ditentukan sebagai urusan Pemerintah Pusat (Pasal 18 ayat 5).\nAyat ini dirumuskan dalam Perubahan Kedua (2000).\nCara cepat: 'Mengurus sendiri' berarti otonomi; tugas dari pusat yang dikerjakan daerah disebut tugas pembantuan.","o":["desentralisasi penuh tanpa batas","otonomi dan tugas pembantuan","federalisme dan otonomi","sentralisasi dan dekonsentrasi","dekonsentrasi saja"],"s":[0,1,0,0,0],"w":["Menurut Pasal 18 ayat (2) UUD NRI 1945, jawabannya “otonomi dan tugas pembantuan”, bukan “desentralisasi penuh tanpa batas”.","Benar. Ini sesuai Pasal 18 ayat (2) UUD NRI 1945.","Menurut Pasal 18 ayat (2) UUD NRI 1945, jawabannya “otonomi dan tugas pembantuan”, bukan “federalisme dan otonomi”.","Menurut Pasal 18 ayat (2) UUD NRI 1945, jawabannya “otonomi dan tugas pembantuan”, bukan “sentralisasi dan dekonsentrasi”.","Menurut Pasal 18 ayat (2) UUD NRI 1945, jawabannya “otonomi dan tugas pembantuan”, bukan “dekonsentrasi saja”."],"h":"'Mengurus sendiri' berarti otonomi; tugas dari pusat yang dikerjakan daerah disebut tugas pembantuan."},{"i":2838,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Menurut UUD NRI 1945 setelah perubahan, kedaulatan berada di tangan rakyat dan …","e":"Pasal 1 ayat (2) UUD NRI 1945 berbunyi: “Kedaulatan berada di tangan rakyat dan dilaksanakan menurut Undang-Undang Dasar.”\nNaskah asli Pasal 1 ayat (2) berbunyi: kedaulatan adalah di tangan rakyat, dan dilakukan sepenuhnya oleh Majelis Permusyawaratan Rakyat.\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Perubahan Ketiga mengakhiri MPR sebagai lembaga tertinggi: kedaulatan tidak lagi dipegang satu lembaga, tetapi dijalankan menurut pembagian dalam konstitusi.","o":["dilakukan sepenuhnya oleh Majelis Permusyawaratan Rakyat","dijalankan oleh partai politik","dilaksanakan oleh Presiden","diwakilkan kepada Dewan Perwakilan Rakyat","dilaksanakan menurut Undang-Undang Dasar"],"s":[0,0,0,0,1],"w":["Menurut Pasal 1 ayat (2) UUD NRI 1945, jawabannya “dilaksanakan menurut Undang-Undang Dasar”, bukan “dilakukan sepenuhnya oleh Majelis Permusyawaratan Rakyat”.","Menurut Pasal 1 ayat (2) UUD NRI 1945, jawabannya “dilaksanakan menurut Undang-Undang Dasar”, bukan “dijalankan oleh partai politik”.","Menurut Pasal 1 ayat (2) UUD NRI 1945, jawabannya “dilaksanakan menurut Undang-Undang Dasar”, bukan “dilaksanakan oleh Presiden”.","Menurut Pasal 1 ayat (2) UUD NRI 1945, jawabannya “dilaksanakan menurut Undang-Undang Dasar”, bukan “diwakilkan kepada Dewan Perwakilan Rakyat”.","Benar. Ini sesuai Pasal 1 ayat (2) UUD NRI 1945."],"h":"Perubahan Ketiga mengakhiri MPR sebagai lembaga tertinggi: kedaulatan tidak lagi dipegang satu lembaga, tetapi dijalankan menurut pembagian dalam konstitusi."},{"i":2839,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Pasal 1 ayat (3) UUD NRI 1945 menegaskan bahwa Negara Indonesia adalah …","e":"Pasal 1 ayat (3) UUD NRI 1945 berbunyi: “Negara Indonesia adalah negara hukum.”\nAyat ini dirumuskan dalam Perubahan Ketiga (2001).\nCara cepat: Pasal 1 memuat tiga identitas: bentuk negara, kedaulatan rakyat, dan dasar penyelenggaraan yang tunduk pada aturan, bukan pada kekuasaan.","o":["negara serikat","negara federal","negara hukum","negara kekuasaan","negara agama"],"s":[0,0,1,0,0],"w":["Menurut Pasal 1 ayat (3) UUD NRI 1945, jawabannya “negara hukum”, bukan “negara serikat”.","Menurut Pasal 1 ayat (3) UUD NRI 1945, jawabannya “negara hukum”, bukan “negara federal”.","Benar. Ini sesuai Pasal 1 ayat (3) UUD NRI 1945.","Menurut Pasal 1 ayat (3) UUD NRI 1945, jawabannya “negara hukum”, bukan “negara kekuasaan”.","Menurut Pasal 1 ayat (3) UUD NRI 1945, jawabannya “negara hukum”, bukan “negara agama”."],"h":"Pasal 1 memuat tiga identitas: bentuk negara, kedaulatan rakyat, dan dasar penyelenggaraan yang tunduk pada aturan, bukan pada kekuasaan."},{"i":2840,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Menurut Pasal 1 ayat (1), Negara Indonesia ialah Negara Kesatuan yang berbentuk …","e":"Pasal 1 ayat (1) UUD NRI 1945 berbunyi: “Negara Indonesia ialah Negara Kesatuan, yang berbentuk Republik.”\nKhusus mengenai bentuk Negara Kesatuan Republik Indonesia tidak dapat dilakukan perubahan (Pasal 37 ayat 5).\nBunyi ini sudah ada sejak naskah asli UUD 1945.\nCara cepat: Bentuk negaranya kesatuan, dan kepala negaranya presiden yang dipilih, bukan raja.","o":["Kerajaan","Persemakmuran","Republik","Federasi","Serikat"],"s":[0,0,1,0,0],"w":["Menurut Pasal 1 ayat (1) UUD NRI 1945, jawabannya “Republik”, bukan “Kerajaan”.","Menurut Pasal 1 ayat (1) UUD NRI 1945, jawabannya “Republik”, bukan “Persemakmuran”.","Benar. Ini sesuai Pasal 1 ayat (1) UUD NRI 1945.","Menurut Pasal 1 ayat (1) UUD NRI 1945, jawabannya “Republik”, bukan “Federasi”.","Menurut Pasal 1 ayat (1) UUD NRI 1945, jawabannya “Republik”, bukan “Serikat”."],"h":"Bentuk negaranya kesatuan, dan kepala negaranya presiden yang dipilih, bukan raja."},{"i":2841,"k":"skd.twk.ketatanegaraan","j":"pilgan","v":3,"q":"Menurut Pasal 25A, Negara Kesatuan Republik Indonesia adalah sebuah negara kepulauan yang berciri …","e":"Pasal 25A UUD NRI 1945 berbunyi: “Negara Kesatuan Republik Indonesia adalah sebuah negara kepulauan yang berciri Nusantara dengan wilayah yang batas-batas dan hak-haknya ditetapkan dengan undang-undang.”\nBatas-batas dan hak-hak wilayahnya ditetapkan dengan undang-undang.\nAyat ini dirumuskan dalam Perubahan Kedua (2000).\nCara cepat: Wawasan kebangsaan Indonesia memandang laut sebagai pemersatu pulau-pulau; nama wawasan itulah cirinya.","o":["Nusantara","kontinental","agraris","maritim","Melayu"],"s":[1,0,0,0,0],"w":["Benar. Ini sesuai Pasal 25A UUD NRI 1945.","Menurut Pasal 25A UUD NRI 1945, jawabannya “Nusantara”, bukan “kontinental”.","Menurut Pasal 25A UUD NRI 1945, jawabannya “Nusantara”, bukan “agraris”.","Menurut Pasal 25A UUD NRI 1945, jawabannya “Nusantara”, bukan “maritim”.","Menurut Pasal 25A UUD NRI 1945, jawabannya “Nusantara”, bukan “Melayu”."],"h":"Wawasan kebangsaan Indonesia memandang laut sebagai pemersatu pulau-pulau; nama wawasan itulah cirinya."}];
